export const dynamic = 'force-dynamic'

import { NextRequest, NextResponse } from 'next/server'
import { logger } from '@/lib/logger'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { sendTemplatedEmail } from '@/lib/email-templates'
import { db, setCurrentUserId } from '@/lib/db'
import { createEmailVerificationToken } from '@/lib/auth/emailVerification'

// AUTO-GENERATED by api-row-sweep --apply — column types from migrations/*.sql + name heuristics.
// pg returns bigint/numeric as string, timestamptz as Date; nullable columns carry `| null`; REVIEW.
interface UserSubscriptionRow {
  id: string
}
export async function POST(_req: NextRequest) {
  const session = await getServerSession(authOptions)
  if (!session?.user?.id) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }
  setCurrentUserId(String(session.user.id))

  const accountResult = await db.query<{ email: string; full_name: string | null; email_verified: boolean }>(
    'SELECT email, full_name, email_verified FROM users WHERE id = $1 LIMIT 1',
    [session.user.id],
  )
  const account = accountResult.rows[0]
  let verificationEmailSent: boolean | null = null
  if (account && !account.email_verified) {
    try {
      const token = createEmailVerificationToken(String(session.user.id), account.email)
      const appUrl = process.env.NEXT_PUBLIC_APP_URL || 'https://metardu.space'
      const verifyUrl = new URL('/email/verify', appUrl)
      verifyUrl.searchParams.set('token', token)
      const result = await sendTemplatedEmail('emailVerification', {
        to: account.email,
        name: account.full_name || session.user.name || '',
        verifyUrl: verifyUrl.toString(),
      }).catch((error: unknown) => {
        logger.warn('[register-complete] Verification email failed:', { error })
        return {
          success: false,
          error: error instanceof Error ? error.message : 'Verification email failed',
        }
      })
      verificationEmailSent = result.success
      if (!result.success) logger.warn('[register-complete] Verification email not sent:', { error: result.error })
    } catch (error) {
      verificationEmailSent = false
      logger.warn('[register-complete] Could not create email verification link:', { error })
    }
  }

  const existingSub = await db.query<UserSubscriptionRow>(
    'SELECT id FROM user_subscriptions WHERE user_id = $1',
    [session.user.id]
  )

  if (existingSub.rows.length > 0) {
    return NextResponse.json({ ok: true, verificationEmailSent })
  }

  const now = new Date()
  await db.query<never>(
    `INSERT INTO user_subscriptions 
     (user_id, plan_id, status, trial_ends_at, current_period_start, current_period_end)
     VALUES ($1, 'pro', 'trial', $2, $3, $4)`,
    [
      session.user.id,
      new Date(now.getTime() + 14 * 24 * 60 * 60 * 1000).toISOString(),
      now.toISOString(),
      new Date(now.getTime() + 30 * 24 * 60 * 60 * 1000).toISOString()
    ]
  )

  // Fire-and-forget welcome email — don't block the response. Sent directly
  // through the template registry (the previous self-HTTP fetch carried no
  // session cookie, so /api/emails/welcome always 401'd and the email never
  // fired), and with the REAL trial end date we just persisted.
  const userEmail = session.user.email
  const userName = session.user.name
  if (userEmail) {
    void sendTemplatedEmail('welcome', {
      to: userEmail,
      name: userName || '',
      trialEndsAt: new Date(now.getTime() + 14 * 24 * 60 * 60 * 1000).toISOString(),
    }).then((res) => {
      if (!res.success && res.error !== 'Email service not configured') {
        logger.warn('[register-complete] Welcome email not sent:', { error: res.error })
      }
    })
  }

  return NextResponse.json({ ok: true, verificationEmailSent })
}
